 41→// GetHookNames returns the hook verbs Claude Code supports.
 42→// These become subcommands: entire hooks claude-code <verb>
 43→func (c *ClaudeCodeAgent) GetHookNames() []string {
 44→	return []string{
 45→		HookNameSessionStart,
 46→		HookNameSessionEnd,
 47→		HookNameStop,
 48→		HookNameUserPromptSubmit,
