400→	// Use repo root to find .claude directory when run from a subdirectory
401→	repoRoot, err := paths.RepoRoot()
402→	if err != nil {
403→		repoRoot = "." // Fallback to CWD if not in a git repo
404→	}
405→	settingsPath := filepath.Join(repoRoot, ".claude", ClaudeSettingsFileName)
406→	data, err := os.ReadFile(settingsPath) //nolint:gosec // path is constructed from repo root + fixed path
407→	if err != nil {
408→		return false
409→	}
410→
411→	var settings ClaudeSettings
412→	if err := json.Unmarshal(data, &settings); err != nil {
413→		return false
414→	}
415→
416→	// Check for at least one of our hooks (new or old format)
417→	return hookCommandExists(settings.Hooks.Stop, "entire hooks claude-code stop") ||
418→		hookCommandExists(settings.Hooks.Stop, "go run ${CLAUDE_PROJECT_DIR}/cmd/entire/main.go hooks claude-code stop") ||
