438→// Helper functions for hook management
439→
440→func hookCommandExists(matchers []ClaudeHookMatcher, command string) bool {
441→	for _, matcher := range matchers {
442→		for _, hook := range matcher.Hooks {
443→			if hook.Command == command {
444→				return true
445→			}
446→		}
447→	}
448→	return false
449→}
450→
451→func hookCommandExistsWithMatcher(matchers []ClaudeHookMatcher, matcherName, command string) bool {
452→	for _, matcher := range matchers {
453→		if matcher.Matcher == matcherName {
454→			for _, hook := range matcher.Hooks {
455→				if hook.Command == command {
456→					return true
457→				}
458→			}
459→		}
460→	}
461→	return false
462→}
463→
464→func addHookToMatcher(matchers []ClaudeHookMatcher, matcherName, command string) []ClaudeHookMatcher {
465→	entry := ClaudeHookEntry{
466→		Type:    "command",
467→		Command: command,
468→	}
469→
470→	// If no matcher name, add to a matcher with empty string
471→	if matcherName == "" {
472→		for i, matcher := range matchers {
473→			if matcher.Matcher == "" {
474→				matchers[i].Hooks = append(matchers[i].Hooks, entry)
475→				return matchers
476→			}
477→		}
478→		return append(matchers, ClaudeHookMatcher{
479→			Matcher: "",
480→			Hooks:   []ClaudeHookEntry{entry},
481→		})
482→	}
483→
484→	// Find or create matcher with the given name
485→	for i, matcher := range matchers {
486→		if matcher.Matcher == matcherName {
487→			matchers[i].Hooks = append(matchers[i].Hooks, entry)
488→			return matchers
489→		}
490→	}
491→
492→	return append(matchers, ClaudeHookMatcher{
493→		Matcher: matcherName,
494→		Hooks:   []ClaudeHookEntry{entry},
495→	})
496→}
