498→// isEntireHook checks if a command is an Entire hook (old or new format)
499→func isEntireHook(command string) bool {
500→	for _, prefix := range entireHookPrefixes {
501→		if strings.HasPrefix(command, prefix) {
502→			return true
503→		}
504→	}
505→	return false
506→}
507→
508→// removeEntireHooks removes all Entire hooks from a list of matchers (for simple hooks like Stop)
509→func removeEntireHooks(matchers []ClaudeHookMatcher) []ClaudeHookMatcher {
510→	result := make([]ClaudeHookMatcher, 0, len(matchers))
511→	for _, matcher := range matchers {
512→		filteredHooks := make([]ClaudeHookEntry, 0, len(matcher.Hooks))
513→		for _, hook := range matcher.Hooks {
514→			if !isEntireHook(hook.Command) {
515→				filteredHooks = append(filteredHooks, hook)
516→			}
517→		}
518→		// Only keep the matcher if it has hooks remaining
519→		if len(filteredHooks) > 0 {
520→			matcher.Hooks = filteredHooks
521→			result = append(result, matcher)
522→		}
523→	}
524→	return result
525→}
526→
527→// removeEntireHooksFromMatchers removes Entire hooks from tool-use matchers (PreToolUse, PostToolUse)
528→// This handles the nested structure where hooks are grouped by tool matcher (e.g., "Task", "TodoWrite")
529→func removeEntireHooksFromMatchers(matchers []ClaudeHookMatcher) []ClaudeHookMatcher {
530→	// Same logic as removeEntireHooks - both work on the same structure
531→	return removeEntireHooks(matchers)
532→}
